 html=f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Plano Mais</title><meta name="description" content="Mais cuidado para você e sua família. Conheça os planos e benefícios do Mais Assistencial."><meta name="theme-color" content="#213cb1"><link rel="icon" href="/assets/favicon.png"><link rel="stylesheet" href="/style.css"><script src="/app.js" defer></script></head><body><a class="skip" href="#conteudo">Pular para o conteúdo</a><header><div class="wrap nav"><a href="/" aria-label="Mais Assistencial — início"><img class="logo" src="/assets/logo.svg" alt="Mais Assistencial"></a><nav class="links" id="navigation" aria-label="Navegação principal">{links}</nav>{btn('Conhecer os planos','/#planos')}<button class="menu" aria-expanded="false" aria-controls="navigation">Menu</button></div></header><main id="conteudo">{body}</main><footer><div class="wrap"><div class="footer-grid"><div><img class="logo" src="/assets/logo-white.svg" alt="Mais Assistencial"><p>Um plano pra vida toda.<br>Cuidado que faz parte do seu dia.</p></div><div><strong>Explore a Mais</strong>{links}</div><div><strong>Vamos conversar?</strong><a href="tel:08000955651">0800 095 5651</a><p>Segunda a sexta, das 8h às 20h.</p><a href="https://sales.planomais.com.br/">Atendimento e contratação ↗</a></div></div><div class="footer-bottom"><span>© 2026 Mais Assistencial. Todos os direitos reservados.</span><span>Plano assistencial familiar.</span></div></div></footer></body></html>'''
 html=html.replace('<link rel="stylesheet" href="/style.css">','<link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/motion.css">')
 dest=out/route if route else out;dest.mkdir(parents=True,exist_ok=True);(dest/'index.html').write_text(html)
