page('duvidas','Dúvidas frequentes',inner('RESPOSTAS COM CLAREZA','Toda boa escolha começa<br>com informação.','Tire suas dúvidas sobre os planos, os benefícios e os próximos passos.')+'<section class="section wrap"><div class="page-faq">'+faq(faqs)+'</div></section><section class="section wrap"><div class="company"><div><h2>A sua dúvida<br>não está aqui?</h2><p>A equipe Mais pode ajudar com as informações específicas do seu plano.</p></div><div class="contact"><span>Fale com a gente</span><a href="tel:08000955651">0800 095 5651 ↗</a><small>Segunda a sexta, das 8h às 20h.</small></div></div></section>')
